package com.acme.library.lending;

import java.util.List;

/**
 * Enforces the per-borrower cap on concurrently open loans before a checkout is authorised.
 */
public class BorrowingLimitGuard {

    private final LoanRepository loans;
    private final int maxConcurrent;

    public BorrowingLimitGuard(LoanRepository loans, int maxConcurrent) {
        this.loans = loans;
        this.maxConcurrent = maxConcurrent;
    }

    public boolean mayCheckout(String memberId) {
        List<LoanRecord> open = loans.findOpenByMember(memberId);
        return open.size() < maxConcurrent;
    }

    public void assertMayCheckout(String memberId) {
        if (!mayCheckout(memberId)) {
            throw new BorrowingLimitExceededException(
                "Member " + memberId + " already holds " + maxConcurrent + " items");
        }
    }
}

class BorrowingLimitExceededException extends RuntimeException {
    public BorrowingLimitExceededException(String message) {
        super(message);
    }
}

