package com.acme.library.fines;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * Computes overdue charges for a returned or still-open loan.
 */
public class OverdueChargeCalculator {

    private final BigDecimal dailyRate;

    public OverdueChargeCalculator(BigDecimal dailyRate) {
        this.dailyRate = dailyRate;
    }

    public BigDecimal chargeFor(LoanRecord loan, LocalDate asOf) {
        LocalDate due = loan.getDueDate();
        if (!asOf.isAfter(due)) {
            return BigDecimal.ZERO;
        }
        long daysLate = ChronoUnit.DAYS.between(due, asOf);
        BigDecimal raw = dailyRate.multiply(BigDecimal.valueOf(daysLate));
        BigDecimal cap = loan.getReplacementValue();
        BigDecimal capped = raw.min(cap);
        return capped.setScale(2, RoundingMode.HALF_UP);
    }
}

