/**
 * Checkout endpoint: reserves a free copy, persists the loan, computes the due date.
 */
@RestController
public class CheckoutController {

    private final CopyService copies;
    private final LoanRepository loans;
    private final BorrowingLimitGuard limitGuard;

    public CheckoutController(CopyService copies, LoanRepository loans, BorrowingLimitGuard limitGuard) {
        this.copies = copies;
        this.loans = loans;
        this.limitGuard = limitGuard;
    }

    @PostMapping("/loans")
    public LoanView checkout(@RequestParam String memberId, @RequestParam String titleId) {
        limitGuard.assertMayCheckout(memberId);
        String copyId = copies.claimFreeCopy(titleId);
        if (copyId == null) {
            throw new NoAvailableCopyException(titleId);
        }
        LocalDate due = LocalDate.now().plusWeeks(2);
        LoanRecord record = loans.save(new LoanRecord(memberId, copyId, due));
        return LoanView.from(record);
    }
}

