import java.time.Instant;
import java.util.List;

/**
 * Queues reservations for unavailable titles and promotes the next member on return.
 */
public class ReservationQueue {

    private final ReservationRepository repo;
    private final NotificationGateway notifier;

    public ReservationQueue(ReservationRepository repo, NotificationGateway notifier) {
        this.repo = repo;
        this.notifier = notifier;
    }

    public Reservation place(String memberId, String titleId) {
        Reservation r = new Reservation(memberId, titleId, Instant.now());
        return repo.save(r);
    }

    public void onCopyReturned(String titleId) {
        List<Reservation> waiting = repo.findWaitingOrdered(titleId);
        if (waiting.isEmpty()) {
            return;
        }
        Reservation next = waiting.get(0);
        next.markReady();
        repo.save(next);
        notifier.send(next.getMemberId(), "Your reserved item is ready for collection");
    }
}

