    public List<CatalogueEntry> search(String term, int page, int size) {
        String pattern = "%" + term.toLowerCase() + "%";
        TypedQuery<CatalogueEntry> q = em.createQuery(
            "SELECT c FROM CatalogueEntry c " +
            "WHERE LOWER(c.title) LIKE :p OR LOWER(c.author) LIKE :p " +
            "ORDER BY c.title", CatalogueEntry.class);
        q.setParameter("p", pattern);
        q.setFirstResult(page * size);
        q.setMaxResults(size);
        return q.getResultList();
    }
}

