import java.time.LocalDate;

/**
 * Processes a return: closes the loan, frees the copy, and records any late charge.
 */
public class ReturnProcessor {

    private final LoanRepository loans;
    private final CopyService copies;
    private final OverdueChargeCalculator calculator;
    private final ChargeLedger ledger;

    public ReturnProcessor(LoanRepository loans, CopyService copies,
                           OverdueChargeCalculator calculator, ChargeLedger ledger) {
        this.loans = loans;
        this.copies = copies;
        this.calculator = calculator;
        this.ledger = ledger;
    }

    public void process(String loanId) {
        LoanRecord loan = loans.require(loanId);
        loan.close(LocalDate.now());
        loans.save(loan);
        copies.release(loan.getCopyId());
        ledger.record(loan.getMemberId(), calculator.chargeFor(loan, LocalDate.now()));
    }
}

