        this.reservations = reservations;
    }

    public boolean isEligible(LoanRecord loan) {
        if (loan.getRenewalCount() >= MAX_RENEWALS) {
            return false;
        }
        return !reservations.hasPendingForCopy(loan.getCopyId());
    }

    public void assertEligible(LoanRecord loan) {
        if (!isEligible(loan)) {
            throw new RenewalNotPermittedException(loan.getId());
        }
    }
}

