 */
public class LoanAuditWriter {

    private final EntityManager em;

    public LoanAuditWriter(EntityManager em) {
        this.em = em;
    }

    public void record(String memberId, String copyId, String action) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            AuditEntry entry = new AuditEntry();
            entry.setMember(memberId);
            entry.setCopy(copyId);
            entry.setAction(action);
            entry.setOccurredAt(Instant.now());
            em.persist(entry);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

