#include <stdio.h>
#include <string.h>
#include "library_db.h"

int close_oldest_open_loan(const char *barcode, char *out_loan_id, size_t out_len) {
    db_cursor_t *cur = NULL;
    if (db_open_loan_cursor(&cur, barcode) != DB_OK) {
        return -1;
    }

    loan_row_t row;
    int matched = 0;
    while (db_loan_cursor_next(cur, &row) == DB_OK) {
        if (row.returned_on != NULL) {
            continue;
        }
        snprintf(out_loan_id, out_len, "%s", row.loan_id);
        matched = 1;
        break; /* cursor is ordered by checked_out_on ascending */
    }
    db_close_cursor(cur);

    if (!matched) {
        fprintf(stderr, "no open loan for barcode %s\n", barcode);
        return -2;
    }

    char now[32];
    db_current_timestamp(now, sizeof(now));
    return db_update_loan_returned(out_loan_id, now);
}

